import type { Metadata } from 'next'
import { BackButton } from '../../../components/NavigationButtons'
import { getPost, getPostComments, getPosts } from '../../../lib/posts'

interface BlogPostParams {
  id: string
}

interface BlogPostProps {
  params: Promise<BlogPostParams>
}

export const revalidate = 300
export const dynamicParams = true

export async function generateStaticParams(): Promise<BlogPostParams[]> {
  const posts = await getPosts()

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }))
}

export async function generateMetadata({
  params,
}: BlogPostProps): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)
  const description = post.body.substring(0, 160)

  return {
    title: `${post.title} - My Blog`,
    description,
    openGraph: { title: post.title, description },
  }
}

export default async function BlogPost({ params }: BlogPostProps) {
  const { id } = await params
  const [post, comments] = await Promise.all([getPost(id), getPostComments(id)])

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}
