export interface Post {
  userId: number
  id: number
  title: string
  body: string
}

export interface PostComment {
  postId: number
  id: number
  name: string
  email: string
  body: string
}

const postsUrl = 'https://jsonplaceholder.typicode.com/posts'

export async function getRecentPosts(): Promise<Post[]> {
  const response = await fetch(`${postsUrl}?_limit=5`, { cache: 'no-store' })

  if (!response.ok) {
    throw new Error('Failed to fetch recent posts')
  }

  return response.json()
}

export async function getPosts(): Promise<Post[]> {
  const response = await fetch(postsUrl, { next: { revalidate: 60 } })

  if (!response.ok) {
    throw new Error('Failed to fetch posts')
  }

  return response.json()
}

export async function getPost(id: string): Promise<Post> {
  const response = await fetch(`${postsUrl}/${encodeURIComponent(id)}`, {
    next: { revalidate: 300 },
  })

  if (response.status === 404) {
    notFound()
  }

  if (!response.ok) {
    throw new Error('Failed to fetch post')
  }

  const post: Post = await response.json()

  if (!post.id) {
    notFound()
  }

  return post
}

export async function getPostComments(id: string): Promise<PostComment[]> {
  const response = await fetch(`${postsUrl}/${encodeURIComponent(id)}/comments`, {
    next: { revalidate: 300 },
  })

  if (!response.ok) {
    throw new Error('Failed to fetch comments')
  }

  return response.json()
}

